class Hlc(private var wall: Long = 0, private var counter: Int = 0, val node: String) {
    @Synchronized fun now(physical: Long): String {
        if (physical > wall) { wall = physical; counter = 0 } else counter++
        return format()
    }
    @Synchronized fun observe(remote: String, physical: Long): String {
        val (rw, rc) = parse(remote)
        val newWall = maxOf(wall, rw, physical)
        counter = when {
            newWall == wall && newWall == rw -> maxOf(counter, rc) + 1
            newWall == wall -> counter + 1
            newWall == rw -> rc + 1
            else -> 0
        }
        wall = newWall
        return format()
    }
    // fixed-width so strings sort correctly: wall(13) - counter(4) - node
    private fun format() = wall.toString().padStart(13, '0') + "-" + counter.toString().padStart(4, '0') + "-" + node
}

type Merge<T> = { merged: T; clashes: (keyof T)[] };

function threeWay<T extends Record<string, unknown>>(base: T, mine: T, theirs: T): Merge<T> {
  const merged = { ...theirs };
  const clashes: (keyof T)[] = [];
  for (const k of Object.keys(mine) as (keyof T)[]) {
    const mineChanged = mine[k] !== base[k];
    const theirsChanged = theirs[k] !== base[k];
    if (mineChanged && !theirsChanged) merged[k] = mine[k];
    else if (mineChanged && theirsChanged && mine[k] !== theirs[k]) clashes.push(k);
  }
  return { merged, clashes };   // no clashes: retry silently. Clashes: show the user both values.
}

