import type { TurboModule } from 'react-native';
import { TurboModuleRegistry } from 'react-native';

export interface Spec extends TurboModule {
  requestSync(reason: string): Promise<void>;           // fire an intent
  enqueueUpload(localPath: string, entityId: string): Promise<string>; // returns upload id
  cancelUpload(uploadId: string): Promise<void>;
  addListener(eventName: string): void;                  // required by NativeEventEmitter
  removeListeners(count: number): void;
}
export default TurboModuleRegistry.getEnforcing<Spec>('NativeSyncEngine');

