class NativeSyncEngineModule(ctx: ReactApplicationContext) : NativeSyncEngineSpec(ctx) {
    private val engine = SyncEngine.get(ctx)            // same singleton the Worker uses
    override fun getName() = "NativeSyncEngine"
    override fun requestSync(reason: String, p: Promise) { engine.requestSync(reason); p.resolve(null) }
    override fun enqueueUpload(path: String, entityId: String, p: Promise) =
        p.resolve(engine.transfers.enqueue(path, entityId))
    // engine.events -> emit coarse 'syncStateChanged' to JS. Data itself is read from SQLite.
}

class SyncWorker(ctx: Context, params: WorkerParameters) : CoroutineWorker(ctx, params) {
    override suspend fun doWork(): Result =
        if (SyncEngine.get(applicationContext).runOnce()) Result.success() else Result.retry()
}

